<script setup lang="ts">
import {onUnmounted,shallowRef,ref,watch} from 'vue';import {useApplication} from '../../application';import type {RecordingSession,RecordingPart} from './recording-types';
const props=defineProps<{meetingId:string|null}>(),{session,recordingStore}=useApplication(),saved=shallowRef<RecordingSession|null>(null),error=ref<string|null>(null),busy=ref(false),urls=new Set<string>();let generation=0;
const stop=watch(()=>[session.current.value?.actor.enterpriseId,props.meetingId],async()=>{const turn=++generation,actor=session.current.value?.actor.enterpriseId;saved.value=null;error.value=null;for(const url of urls)URL.revokeObjectURL(url);urls.clear();if(!actor)return;try{const meeting=props.meetingId??await recordingStore.latest(actor);if(!meeting)return;const value=await recordingStore.load(actor,meeting);if(turn===generation&&session.current.value?.actor.enterpriseId===actor)saved.value=value;}catch(cause){if(turn===generation)error.value=cause instanceof Error?cause.message:'旧版录音暂不可读取';}},{immediate:true});
async function download(part:RecordingPart){if(busy.value||!saved.value)return;const turn=generation,record=saved.value;busy.value=true;error.value=null;try{const file=await recordingStore.file(record,part);if(turn!==generation||session.current.value?.actor.enterpriseId!==record.actor)return;const url=URL.createObjectURL(file);urls.add(url);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url);},30000);}catch(cause){if(turn===generation)error.value=cause instanceof Error?cause.message:'旧版录音下载未完成';}finally{if(turn===generation)busy.value=false;}}
onUnmounted(()=>{stop();generation++;for(const url of urls)URL.revokeObjectURL(url);});
</script>
<template><section v-if="saved?.parts.some(p=>p.bytes>0)||error" class="card mt16" aria-label="本机旧版录音"><div class="card-h"><h2 class="card-t">本机旧版录音</h2></div><div class="p16"><p class="small muted">以下为旧版浏览器已保存的片段，可下载保留。新录音使用服务端分片保存；旧文件会继续保留在本机。</p><div v-for="part in saved?.parts.filter(p=>p.bytes>0)??[]" :key="part.id" class="between mt12"><span>{{part.name}}</span><button class="btn sm" :disabled="busy" @click="download(part)">下载</button></div><p v-if="error" role="alert" class="ac-error">{{error}}</p></div></section></template>
